import 'package:flutter/material.dart';
import '../theme/app_theme.dart';

class ZayloCard extends StatelessWidget { const ZayloCard({super.key, required this.child, this.onTap}); final Widget child; final VoidCallback? onTap; @override Widget build(BuildContext context)=>Card(child: InkWell(borderRadius: BorderRadius.circular(ZayloRadius.md), onTap:onTap, child:Padding(padding: const EdgeInsets.all(16), child: child))); }
class SectionHeader extends StatelessWidget { const SectionHeader(this.title,{super.key,this.action}); final String title; final Widget? action; @override Widget build(BuildContext context)=>Padding(padding: const EdgeInsets.only(top:20,bottom:8), child: Row(children:[Expanded(child:Text(title,style:Theme.of(context).textTheme.titleLarge)), if(action!=null) action!])); }
class StateView extends StatelessWidget { const StateView({super.key, required this.icon, required this.title, required this.message}); final IconData icon; final String title,message; @override Widget build(BuildContext context)=>Center(child:Padding(padding:const EdgeInsets.all(24), child:Column(mainAxisSize:MainAxisSize.min, children:[Icon(icon,size:44), const SizedBox(height:12), Text(title,style:Theme.of(context).textTheme.titleMedium), Text(message,textAlign:TextAlign.center)]))); }
class TrustBadge extends StatelessWidget { const TrustBadge(this.verified,{super.key}); final bool verified; @override Widget build(BuildContext context)=>Chip(avatar:Icon(verified?Icons.verified_outlined:Icons.pending_outlined,size:16), label:Text(verified?'Verified':'Unverified'), visualDensity:VisualDensity.compact); }
void showComingSoon(BuildContext context, String label)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$label is ready for backend connection in a later MVP.')));
